    persona_variants: { tiny_tyrant: { title: 'Facial Surveillance Drill', one_line_description: "Move your face slowly across the visual field and let the Commandant track.", full_instructions: ["Position {name} supine, or upon the lap facing you.", "Bring your face into range — approximately 25 to 30 cm — and obtain visual lock.", "Move your head slowly to one side. Slowly.", "Pause. Allow the Commandant's gaze to catch up. Then return.", "Provide accompanying narration: \"There you are... and here.\""], cta: 'Drill concluded →', card_cta: 'Begin the briefing →' } },
    principle_id: PRINCIPLES.VISUAL_TRACKING_CONTRAST, principle_explanation: "Babies see best at about 20 to 30 cm in their early months. Following your face teaches their eyes to track smoothly — a building block of visual attention.", source_citations: [{ organisation: 'Raising Children Network', citation_title: 'Newborn vision development', url: 'AU_SOURCE_URL' }, { organisation: 'NHS', citation_title: "Your baby's vision", url: 'UK_SOURCE_URL' }],
