    principle_id: PRINCIPLES.VISUAL_TRACKING_CONTRAST, principle_explanation: 'High-contrast patterns are what young babies can see most clearly. Looking at them builds focus and helps their visual system mature.', source_citations: [{ organisation: 'Raising Children Network', citation_title: 'Reading and babies', url: 'AU_SOURCE_URL' }, { organisation: 'BBC Tiny Happy People', citation_title: 'Books for babies', url: 'UK_SOURCE_URL' }],
