    persona_variants: { tiny_tyrant: { title: 'The Auditory Inspection Tour', one_line_description: "Carry {name} on a tour of the household's sound profile.", full_instructions: ["Hoist {name} into the carry position so they may see and hear what you do.", "Proceed slowly through the operational rooms.", "Halt at each significant sound source. Identify it: \"Kettle. Fan. The dog.\"", "Permit assessment before relocating.", "Four or five stations is sufficient. Conclude in a quiet sector."], cta: 'Tour concluded →', card_cta: 'Begin the briefing →' } },
    principle_id: PRINCIPLES.AUDITORY_AWARENESS, principle_explanation: 'Everyday sounds are full of information. Naming them connects what your baby hears to language and helps them tune into their world.', source_citations: [{ organisation: 'Raising Children Network', citation_title: 'Talking and listening with babies', url: 'AU_SOURCE_URL' }, { organisation: 'BBC Tiny Happy People', citation_title: 'Why talking to your baby matters', url: 'UK_SOURCE_URL' }],
